coding.solution:
def quantize(weights):
    m = max(abs(w) for w in weights)
    scale = m / 127 if m else 1.0
    q = [max(-127, min(127, round(w / scale))) for w in weights]
    return q, scale

def dequantize(q, scale):
    return [v * scale for v in q]

def max_error(weights):
    q, s = quantize(weights)
    return max(abs(a - b) for a, b in zip(weights, dequantize(q, s)))

