coding.solution:
def majority_answer(answers):
    if not answers:
        return None, 0.0
    counts = {}
    for a in answers:
        k = a.strip().lower()
        counts[k] = counts.get(k, 0) + 1
    best = max(counts, key=counts.get)
    return best, round(counts[best] / len(answers), 2)
